from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {c: i for i, c in enumerate(alphabet)}

    # Build Aho-Corasick trie
    children: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            if children[node][c] == -1:
                children[node][c] = len(children)
                children.append([-1] * k)
                bad.append(False)
            node = children[node][c]
        bad[node] = True

    # Build failure links and complete transition table
    num_states = len(children)
    fail = [0] * num_states
    q = deque()

    for c in range(k):
        nxt = children[0][c]
        if nxt != -1:
            q.append(nxt)
        else:
            children[0][c] = 0

    while q:
        u = q.popleft()
        bad[u] = bad[u] or bad[fail[u]]
        for c in range(k):
            v = children[u][c]
            if v != -1:
                fail[v] = children[fail[u]][c]
                q.append(v)
            else:
                children[u][c] = children[fail[u]][c]

    # Map non-bad states to [0..m-1]
    state_map = [-1] * num_states
    good_states = []
    for s in range(num_states):
        if not bad[s]:
            state_map[s] = len(good_states)
            good_states.append(s)

    m = len(good_states)
    mat = [[0] * m for _ in range(m)]
    for i, s in enumerate(good_states):
        for c in range(k):
            ns = children[s][c]
            if not bad[ns]:
                mat[i][state_map[ns]] += 1

    def mat_mul(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            row_i = A[i]
            res_i = res[i]
            for j in range(m):
                a_ij = row_i[j]
                if a_ij:
                    row_b = B[j]
                    for l in range(m):
                        res_i[l] = (res_i[l] + a_ij * row_b[l]) % MOD
        return res

    # Binary exponentiation: compute vec * mat^n
    vec = [0] * m
    vec[0] = 1
    power = mat
    exp = n

    while exp > 0:
        if exp & 1:
            new_vec = [0] * m
            for i in range(m):
                v_i = vec[i]
                if v_i:
                    row_p = power[i]
                    for j in range(m):
                        new_vec[j] = (new_vec[j] + v_i * row_p[j]) % MOD
            vec = new_vec
        exp >>= 1
        if exp > 0:
            power = mat_mul(power, power)

    return sum(vec) % MOD
